#!/usr/bin/env node
// V2V fix 6 - backup translation (Transcribe + Translate + Polly) when Nova Sonic is down, plus a switch.
//   1. Each side of the call (agent -> customer, customer -> agent) moves to the backup on its own, at
//      once, when its Nova Sonic session does not start, fails during the call, or goes silent (a
//      sentence Transcribe heard with no Nova Sonic event of any kind within 6 s; on the customer side,
//      speech on the line followed by 10 s with no Nova Sonic event). A sign-in problem is not treated as
//      a Nova Sonic failure and is reported as before.
//   2. On the backup, every sentence is transcribed, translated and spoken by Polly, in order. The four
//      boxes (Agent said, Translated to customer, Customer said, Translated to agent) and the transcript
//      keep filling. What the agent said that Nova Sonic had not translated yet is spoken first. The
//      customer's Transcribe runs only while the customer side is on the backup. Typed messages go
//      through the backup too.
//   3. Nova Sonic is restarted in the background (at most 3 attempts, 1.5 / 3 / 4.5 s apart). When one
//      works, Nova Sonic takes over again at the next quiet moment; until then it is muted. After 3
//      failed attempts the backup continues for the rest of the call. A failure is remembered for 5
//      minutes: calls started meanwhile begin on the backup and try Nova Sonic in the background.
//   4. Switch: the Parameter Store setting <hierarchy>forceBackupTranslation. "true" puts every call on
//      the backup (new calls at once, calls in progress within about a minute); any other value, or no
//      setting, means Nova Sonic. The proxy reads it every 30 s (read-only permission on that one
//      parameter); it is not part of "npm run configure", and changing it needs no deployment.
//   5. While a side is on Nova Sonic nothing it plays or shows changes: its output passes through
//      unchanged and fix 4's checks run as before. Nova Sonic's view of the microphone no longer destroys
//      the microphone when a session ends, so the agent's Transcribe keeps hearing it during a restart
//      (every explicit shutdown of the microphone is unchanged).
//   6. Fixed: a failed Start left its Transcribe stream and microphone capture running.
//   7. Proxy: GET /api/translation-mode, the Parameter Store client, and 150 Translate + Polly requests
//      per minute per agent (was 60). Logs: [BACKUP] lines and one [BACKUP-SUMMARY] line per call.
//
// Run from the project root (the folder that contains cdk-stacks, webapp, proxy and SETUP.md):
//   node apply-v2v-fix-6.cjs            check only: reports what it would do, changes nothing
//   node apply-v2v-fix-6.cjs --apply    applies everything, or nothing if any check fails
//
// - Applies on top of fix 4 and fix 5. Edits 3 webapp files, 6 proxy files, 1 CDK file
//   (cdk-stacks/lib/proxy/proxy-stack.ts) and proxy/README.md in place, and creates 3 new files
//   (webapp/utils/backupTranslation.js, proxy/src/services/translationMode.js and its test). Each edit
//   replaces one exact block of text; if that block is not found exactly once, nothing is changed and the
//   file is reported. Any other changes you have in those files are kept. The README edit is optional.
// - Reports whether every resulting file matches the version the tests ran against.
// - Backs up every file it modifies or overwrites to v2v-backup-<timestamp>/ first.
// - Works with either Windows (CRLF) or Unix (LF) line endings, and is safe to run twice.
// - The deploy (cdk-stacks: npm run build:deploy:all) rebuilds the proxy image (it installs one new
//   package, @aws-sdk/client-ssm, pinned in package-lock.json) and the webapp.
"use strict";
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const NEW_FILES = {
 "webapp/utils/backupTranslation.js": "// Copyright 2025 Amazon.com, Inc. or its affiliates. All Rights Reserved.\n// SPDX-License-Identifier: MIT-0\n//\n// fix 6: backup translation when Nova Sonic is down.\n//\n// Each side of the call (agent -> customer, customer -> agent) runs on Nova Sonic. When Nova Sonic fails\n// on a side (it does not start, its stream fails, or it goes silent) or the forceBackupTranslation switch\n// is on, that side is translated by Amazon Transcribe -> Amazon Translate -> Amazon Polly instead, one\n// sentence at a time. Nova Sonic is restarted in the background (at most 3 attempts per failure); once a\n// restart works, Nova Sonic takes over again at the next quiet moment.\n//\n// Everything here is independent of the page: timers, clocks, audio and services are passed in, so the\n// behaviour can be tested in Node. main.js wires it to the call.\nimport { wordsContainedIn } from \"./translationGuards\";\n\nexport const BACKUP_MAX_ATTEMPTS = 3;\n// Same spacing as the existing Nova Sonic reconnects: 1.5 s, 3 s, 4.5 s.\nexport const BACKUP_BACKOFF_MS = (attempt) => attempt * 1500;\n// Transcribe sometimes closes one sentence as two results within a few hundred milliseconds.\nexport const BACKUP_JOIN_MS = 250;\n// Nova Sonic is judged silent when a sentence Transcribe heard got no Nova Sonic event of any kind (not\n// even its own transcript of what it heard) from GRACE_BEFORE before the sentence ended to WAIT after it.\nexport const SILENCE_WAIT_MS = 6000;\nexport const SILENCE_GRACE_BEFORE_MS = 3000;\n// Sentences this short (\"ok\", \"the\") are not judged.\nexport const SILENCE_MIN_WORDS = 3;\nexport const SILENCE_MIN_CHARS = 12;\n// A sentence that ends this soon after a Nova Sonic session started is not judged: the session may\n// have heard only its end.\nexport const SILENCE_SESSION_SETTLE_MS = 4000;\n// At most this many silence switches per side per call, so a line that confuses the check cannot make\n// the call flip back and forth.\nexport const SILENCE_MAX_TRIGGERS = 2;\n// Customer side (no Transcribe while Nova Sonic works): speech on the line, then no Nova Sonic event.\nexport const VOICE_THRESHOLD_RMS = 0.02;\nexport const VOICE_MIN_VOICED_MS = 2000;\nexport const VOICE_BURST_GAP_MS = 1000;\nexport const VOICE_WAIT_MS = 10000;\nexport const VOICE_MAX_TRIGGERS = 1;\n// Handing back to Nova Sonic only at a quiet moment.\nexport const HANDOVER_POLL_MS = 250;\nexport const HANDOVER_MIN_RETURNING_MS = 1500;\nexport const HANDOVER_QUIET_AFTER_SENTENCE_MS = 4000;\nexport const HANDOVER_QUIET_NOVA_MS = 2500;\nexport const HANDOVER_QUIET_VOICE_MS = 1000;\n// Without a working level meter, this long without a sentence counts as quiet.\nexport const HANDOVER_QUIET_NO_METER_MS = 6000;\n// Polly MP3 is at most 48 kbit/s; assuming 32 kbit/s over-estimates how long a clip plays, which is the\n// safe side when deciding the line is quiet.\nconst ASSUMED_MP3_BYTES_PER_SECOND = 4000;\n\nconst defaultTimers = {\n  setTimeout: (fn, ms) => setTimeout(fn, ms),\n  clearTimeout: (id) => clearTimeout(id),\n  setInterval: (fn, ms) => setInterval(fn, ms),\n  clearInterval: (id) => clearInterval(id),\n};\n\nconst words = (text) => String(text || \"\").trim().split(/\\s+/).filter(Boolean);\n\n/**\n * True when `text` (what Transcribe heard on one side) is mostly words that were just spoken to that\n * side: the translation played to the customer coming back through their phone.\n * @param {string} text\n * @param {string[]} recentlySpoken\n */\nexport function isLikelyEcho(text, recentlySpoken) {\n  if (words(text).length < 3 || !recentlySpoken?.length) return false;\n  return wordsContainedIn(text, recentlySpoken.join(\" \")) >= 0.7;\n}\n\n/**\n * Translates and speaks one side's sentences in order. Translations are fetched in parallel as the\n * sentences arrive, and delivered strictly in the order spoken.\n *\n * @param {object} opts\n * @param {string} opts.label\n * @param {(text: string) => Promise<{text: string, audio: Uint8Array|null, voiceLabel?: string}|null>} opts.translate\n * @param {(job: {text: string}, result: object|null) => Promise<void>} opts.deliver  shows and plays one result\n */\nexport function createBackupSpeaker({ label, translate, deliver, joinMs = BACKUP_JOIN_MS, retryDelayMs = 400, timers = defaultTimers, now = Date.now, log = console }) {\n  const queue = [];\n  let epoch = 0;\n  let pendingText = \"\";\n  let joinTimer = null;\n  let running = null;\n  let lastDeliveredAt = 0;\n  let playbackEndsAt = 0;\n  const waiters = [];\n\n  async function translateWithRetry(text) {\n    let result = await Promise.resolve()\n      .then(() => translate(text))\n      .catch(() => null);\n    if (!result || !result.text) {\n      await new Promise((resolve) => timers.setTimeout(resolve, retryDelayMs));\n      result = await Promise.resolve()\n        .then(() => translate(text))\n        .catch(() => null);\n    }\n    return result && result.text ? result : null;\n  }\n\n  function settleWaiters() {\n    if (!speaker.isIdle()) return;\n    waiters.splice(0).forEach((resolve) => resolve());\n  }\n\n  function pump() {\n    if (running) return;\n    running = (async () => {\n      while (queue.length) {\n        const job = queue[0];\n        let result = null;\n        try {\n          result = await job.result;\n        } catch {\n          result = null;\n        }\n        if (queue[0] === job) queue.shift();\n        if (job.epoch !== epoch) continue;\n        const deliverStartedAt = now();\n        const bytes = result?.audio?.byteLength ?? result?.audio?.length ?? 0;\n        if (bytes > 0) {\n          // Whether or not the player resolves only when the clip has finished, the line is not quiet\n          // before this estimate of its end.\n          playbackEndsAt = Math.max(playbackEndsAt, deliverStartedAt) + Math.ceil((bytes / ASSUMED_MP3_BYTES_PER_SECOND) * 1000);\n        }\n        try {\n          await deliver(job, result);\n        } catch (e) {\n          log.error?.(`[BACKUP] ${label} - could not deliver a sentence`, e);\n        }\n        lastDeliveredAt = now();\n      }\n    })().finally(() => {\n      running = null;\n      if (queue.length) pump();\n      else settleWaiters();\n    });\n  }\n\n  function enqueue(text, prefetched) {\n    const job = { text, epoch, queuedAt: now(), result: null };\n    job.result = prefetched\n      ? Promise.resolve(prefetched)\n          .catch(() => null)\n          .then((r) => (r && r.text ? r : translateWithRetry(text)))\n      : translateWithRetry(text);\n    queue.push(job);\n    pump();\n    return job;\n  }\n\n  function flush() {\n    timers.clearTimeout(joinTimer);\n    joinTimer = null;\n    const text = pendingText.trim();\n    pendingText = \"\";\n    if (text) enqueue(text);\n  }\n\n  const speaker = {\n    /** A sentence Transcribe finished. Joined with one that follows within joinMs. */\n    say(text) {\n      const t = String(text || \"\").trim();\n      if (!t) return;\n      pendingText = pendingText ? `${pendingText} ${t}` : t;\n      timers.clearTimeout(joinTimer);\n      joinTimer = timers.setTimeout(flush, joinMs);\n    },\n    /** Speak at once, optionally with a translation already fetched (the fix 4 prefetch). */\n    speakNow(text, prefetched) {\n      const t = String(text || \"\").trim();\n      if (!t) return;\n      flush();\n      enqueue(t, prefetched);\n    },\n    /** Nothing waiting, translating or playing (by the clip length, whichever ends later). */\n    isIdle() {\n      return !pendingText && !joinTimer && queue.length === 0 && !running && now() >= playbackEndsAt;\n    },\n    whenIdle() {\n      if (speaker.isIdle()) return Promise.resolve();\n      return new Promise((resolve) => waiters.push(resolve));\n    },\n    /** Drops everything not yet delivered; results still in flight are discarded when they arrive. */\n    cancel() {\n      epoch++;\n      timers.clearTimeout(joinTimer);\n      joinTimer = null;\n      pendingText = \"\";\n      queue.length = 0;\n      playbackEndsAt = 0;\n      settleWaiters();\n    },\n    get lastDeliveredAt() {\n      return lastDeliveredAt;\n    },\n    get playbackEndsAt() {\n      return playbackEndsAt;\n    },\n  };\n  return speaker;\n}\n\n/**\n * One side's state: \"nova\" (Nova Sonic translates), \"backup\" (Transcribe + Translate + Polly translate),\n * \"returning\" (Nova Sonic restarted and listening, but muted until the next quiet moment).\n *\n * ops (all provided by main.js):\n *   leaveNova({reason, cause, speakInProgress})  stop Nova Sonic on this side and start the backup\n *   startNova(label) -> Promise<boolean|\"busy\">   start a Nova Sonic session in the background (\"busy\":\n *                                                 another restart is running, try again shortly)\n *   abandonNova()                                 stop a session that started after it was no longer wanted\n *   handoverReady(returningSince) -> boolean      the side is quiet enough to hand back to Nova Sonic\n *   afterHandover()                               Nova Sonic is back: stop the backup\n *   onStateChange(state, detail)                  banner, logs, counters\n *   isCallLive() -> boolean\n *   onNovaHealthy() / onNovaUnhealthy()           optional: remembered for the next calls\n */\nexport function createFailoverController({ label, ops, maxAttempts = BACKUP_MAX_ATTEMPTS, backoffMs = BACKUP_BACKOFF_MS, handoverPollMs = HANDOVER_POLL_MS, timers = defaultTimers, now = Date.now, log = console }) {\n  let state = \"nova\";\n  let cause = null; // \"failure\" | \"switch\" | \"memory\" when not on Nova Sonic\n  let reason = \"\";\n  let attempts = 0;\n  let generation = 0;\n  let attemptTimer = null;\n  let attemptInFlight = false;\n  let handoverTimer = null;\n  let returningSince = 0;\n  let backupSince = 0;\n\n  const notify = (detail) => {\n    try {\n      ops.onStateChange?.(state, { reason, cause, attempts, maxAttempts, ...detail });\n    } catch (e) {\n      log.error?.(`[BACKUP] ${label} - state change handler failed`, e);\n    }\n  };\n\n  function clearAttempt() {\n    timers.clearTimeout(attemptTimer);\n    attemptTimer = null;\n  }\n\n  function stopHandoverPoll() {\n    timers.clearInterval(handoverTimer);\n    handoverTimer = null;\n  }\n\n  function scheduleAttempt(delayMs) {\n    clearAttempt();\n    attemptTimer = timers.setTimeout(() => {\n      attemptTimer = null;\n      attempt();\n    }, delayMs);\n  }\n\n  function enterBackup(newReason, newCause, { speakInProgress = false } = {}) {\n    const from = state;\n    stopHandoverPoll();\n    if (from === \"nova\") backupSince = now();\n    state = \"backup\";\n    reason = newReason;\n    cause = newCause;\n    try {\n      ops.leaveNova({ reason: newReason, cause: newCause, from, speakInProgress: speakInProgress && from === \"nova\" });\n    } catch (e) {\n      log.error?.(`[BACKUP] ${label} - could not switch to backup`, e);\n    }\n    notify({ from });\n  }\n\n  async function attempt() {\n    if (state !== \"backup\" || cause === \"switch\" || attemptInFlight) return;\n    if (!ops.isCallLive()) return;\n    if (attempts >= maxAttempts) return;\n    attempts++;\n    const gen = generation;\n    const n = attempts;\n    attemptInFlight = true;\n    notify({ attempting: n });\n    let ok = false;\n    let busy = false;\n    try {\n      const outcome = await ops.startNova(`${label}-RETRY-${n}`);\n      busy = outcome === \"busy\";\n      ok = outcome === true;\n    } catch (e) {\n      ok = false;\n      log.warn?.(`[BACKUP] ${label} - Nova Sonic restart ${n}/${maxAttempts} failed`, e);\n    } finally {\n      attemptInFlight = false;\n    }\n    if (busy) {\n      // Another restart (Nova Sonic's own renewal, a WebRTC refresh) was running: not an attempt.\n      attempts--;\n      if (gen === generation && state === \"backup\" && cause !== \"switch\") scheduleAttempt(1000);\n      return;\n    }\n    if (gen !== generation || state !== \"backup\" || cause === \"switch\") {\n      // The call ended, the switch went on, or another path moved the side on while this attempt ran.\n      if (ok) {\n        try {\n          ops.abandonNova();\n        } catch (e) {\n          log.error?.(`[BACKUP] ${label} - could not stop an unwanted Nova Sonic session`, e);\n        }\n      }\n      return;\n    }\n    if (ok) {\n      ops.onNovaHealthy?.();\n      beginReturning();\n      return;\n    }\n    ops.onNovaUnhealthy?.();\n    if (attempts < maxAttempts) {\n      scheduleAttempt(backoffMs(attempts));\n      notify({ failedAttempt: n });\n    } else {\n      notify({ failedAttempt: n, exhausted: true });\n    }\n  }\n\n  function beginReturning() {\n    state = \"returning\";\n    returningSince = now();\n    notify({});\n    stopHandoverPoll();\n    handoverTimer = timers.setInterval(() => {\n      if (state !== \"returning\") {\n        stopHandoverPoll();\n        return;\n      }\n      let ready = false;\n      try {\n        ready = ops.handoverReady(returningSince) === true;\n      } catch (e) {\n        log.error?.(`[BACKUP] ${label} - handover check failed`, e);\n      }\n      if (!ready) return;\n      stopHandoverPoll();\n      const backupMs = now() - backupSince;\n      state = \"nova\";\n      cause = null;\n      reason = \"\";\n      attempts = 0;\n      try {\n        ops.afterHandover();\n      } catch (e) {\n        log.error?.(`[BACKUP] ${label} - handover cleanup failed`, e);\n      }\n      notify({ handedOver: true, backupMs });\n    }, handoverPollMs);\n  }\n\n  return {\n    get state() {\n      return state;\n    },\n    get cause() {\n      return cause;\n    },\n    get reason() {\n      return reason;\n    },\n    get attempts() {\n      return attempts;\n    },\n    /** Transcribe's sentences go to the backup, not to the Nova Sonic checks. */\n    routesToBackup() {\n      return state !== \"nova\";\n    },\n    /** Nova Sonic's output on this side is not played or shown. */\n    suppressesNova() {\n      return state !== \"nova\";\n    },\n    /**\n     * Nova Sonic failed on this side (did not start, stream error, silent). Switches to the backup at once\n     * and restarts Nova Sonic in the background. A failure while already on the backup is ignored.\n     */\n    novaFailed(why, { speakInProgress = true } = {}) {\n      if (state === \"backup\") return false;\n      if (!ops.isCallLive()) return false;\n      enterBackup(why, \"failure\", { speakInProgress });\n      ops.onNovaUnhealthy?.();\n      if (attempts < maxAttempts) scheduleAttempt(backoffMs(attempts + 1));\n      else notify({ exhausted: true });\n      return true;\n    },\n    /**\n     * At Start: this side starts on the backup (\"switch\", \"memory\" or \"failure\"). speakInProgress: what\n     * Transcribe heard while Nova Sonic was trying to start is spoken by the backup.\n     */\n    startOnBackup(why, startCause, { speakInProgress = false } = {}) {\n      generation++;\n      clearAttempt();\n      attempts = 0;\n      enterBackup(why, startCause, { speakInProgress });\n      if (startCause !== \"switch\") scheduleAttempt(backoffMs(1));\n    },\n    /** The switch went on: every side goes to the backup and stays there. */\n    switchOn(why) {\n      if (state === \"backup\" && cause === \"switch\") return;\n      generation++;\n      clearAttempt();\n      if (state === \"backup\") {\n        cause = \"switch\";\n        reason = why;\n        notify({});\n        return;\n      }\n      enterBackup(why, \"switch\", { speakInProgress: true });\n    },\n    /** The switch went off: a side on the backup because of the switch tries Nova Sonic again now. */\n    switchOff() {\n      if (state !== \"backup\" || cause !== \"switch\") return;\n      generation++;\n      cause = \"failure\";\n      reason = \"switch turned off\";\n      attempts = 0;\n      notify({});\n      scheduleAttempt(0);\n    },\n    /**\n     * A Nova Sonic session started through the existing restart path (7.5-minute renewal, WebRTC refresh,\n     * language change) while this side was on the backup: treat it like a successful background attempt.\n     */\n    novaSessionStarted() {\n      if (state === \"nova\" || state === \"returning\") return;\n      if (cause === \"switch\") {\n        ops.abandonNova();\n        return;\n      }\n      generation++;\n      clearAttempt();\n      ops.onNovaHealthy?.();\n      beginReturning();\n    },\n    /** Call over: back to the initial state, with every timer stopped. */\n    reset() {\n      generation++;\n      clearAttempt();\n      stopHandoverPoll();\n      state = \"nova\";\n      cause = null;\n      reason = \"\";\n      attempts = 0;\n      attemptInFlight = false;\n    },\n  };\n}\n\n/**\n * Agent side, while Nova Sonic works: a sentence that Transcribe heard, followed by no Nova Sonic event at\n * all (no transcript of its own, no text, no audio), means the session is silent. Stricter than \"slow\":\n * a working Nova Sonic always reports at least what it heard.\n */\nexport function createSilenceWatchdog({ isArmed, onSilent, waitMs = SILENCE_WAIT_MS, graceBeforeMs = SILENCE_GRACE_BEFORE_MS, minWords = SILENCE_MIN_WORDS, minChars = SILENCE_MIN_CHARS, settleMs = SILENCE_SESSION_SETTLE_MS, maxTriggers = SILENCE_MAX_TRIGGERS, timers = defaultTimers, now = Date.now }) {\n  let lastEventAt = 0;\n  let sessionStartedAt = 0;\n  let triggers = 0;\n  const pending = new Set();\n\n  return {\n    noteNovaEvent() {\n      lastEventAt = now();\n    },\n    noteSessionStart() {\n      sessionStartedAt = now();\n    },\n    /** A sentence Transcribe finished. `session` is the Nova Sonic session live at that moment. */\n    noteSentence(text, session) {\n      if (!session || triggers >= maxTriggers || !isArmed(session)) return;\n      const t = String(text || \"\").trim();\n      if (t.length < minChars || words(t).length < minWords) return;\n      const at = now();\n      if (at - sessionStartedAt < settleMs) return;\n      const id = timers.setTimeout(() => {\n        pending.delete(id);\n        if (triggers >= maxTriggers || !isArmed(session)) return;\n        if (lastEventAt >= at - graceBeforeMs) return;\n        triggers++;\n        onSilent({ text: t, heardAt: at, lastEventAt });\n      }, waitMs);\n      pending.add(id);\n    },\n    cancel() {\n      pending.forEach((id) => timers.clearTimeout(id));\n      pending.clear();\n    },\n    reset() {\n      this.cancel();\n      triggers = 0;\n      lastEventAt = 0;\n      sessionStartedAt = 0;\n    },\n    get triggers() {\n      return triggers;\n    },\n  };\n}\n\n/**\n * Customer side, while Nova Sonic works (no Transcribe then): a burst of speech on the customer's line\n * followed by no Nova Sonic event at all. Continuous sound (music, noise) never ends a burst, so it never\n * triggers; only speech-like bursts with pauses are judged.\n *\n * @param {{onSample(fn: (level: number|null) => void): () => void}} opts.meter\n */\nexport function createVoiceWatchdog({ meter, isArmed, currentSession, onSilent, threshold = VOICE_THRESHOLD_RMS, minVoicedMs = VOICE_MIN_VOICED_MS, burstGapMs = VOICE_BURST_GAP_MS, waitMs = VOICE_WAIT_MS, settleMs = SILENCE_SESSION_SETTLE_MS, maxTriggers = VOICE_MAX_TRIGGERS, timers = defaultTimers, now = Date.now }) {\n  let lastEventAt = 0;\n  let sessionStartedAt = 0;\n  let triggers = 0;\n  let burst = null; // { startedAt, lastVoicedAt, voicedMs, lastSampleAt }\n  const pending = new Set();\n  let unsubscribe = null;\n\n  function onSample(level) {\n    const t = now();\n    if (level == null) return;\n    if (level > threshold) {\n      if (!burst) burst = { startedAt: t, lastVoicedAt: t, voicedMs: 0, lastSampleAt: t };\n      burst.voicedMs += Math.min(t - burst.lastSampleAt, 250) || 100;\n      burst.lastVoicedAt = t;\n      burst.lastSampleAt = t;\n      return;\n    }\n    if (!burst) return;\n    burst.lastSampleAt = t;\n    if (t - burst.lastVoicedAt < burstGapMs) return;\n    const ended = burst;\n    burst = null;\n    if (ended.voicedMs < minVoicedMs || triggers >= maxTriggers) return;\n    const session = currentSession();\n    if (!session || !isArmed(session)) return;\n    if (ended.startedAt - sessionStartedAt < settleMs) return;\n    // waitMs after the speech ended, not after the pause was noticed.\n    const id = timers.setTimeout(() => {\n      pending.delete(id);\n      if (triggers >= maxTriggers || !isArmed(session)) return;\n      if (lastEventAt >= ended.startedAt - burstGapMs) return;\n      triggers++;\n      onSilent({ burstStartedAt: ended.startedAt, burstEndedAt: ended.lastVoicedAt, lastEventAt });\n    }, Math.max(0, waitMs - (t - ended.lastVoicedAt)));\n    pending.add(id);\n  }\n\n  return {\n    start() {\n      if (!unsubscribe && meter) unsubscribe = meter.onSample(onSample);\n    },\n    stop() {\n      unsubscribe?.();\n      unsubscribe = null;\n      burst = null;\n      pending.forEach((id) => timers.clearTimeout(id));\n      pending.clear();\n    },\n    noteNovaEvent() {\n      lastEventAt = now();\n    },\n    noteSessionStart() {\n      sessionStartedAt = now();\n    },\n    reset() {\n      this.stop();\n      triggers = 0;\n      lastEventAt = 0;\n      sessionStartedAt = 0;\n    },\n    get triggers() {\n      return triggers;\n    },\n  };\n}\n\n/**\n * Sound level of a MediaStream, sampled every pollMs with an AnalyserNode (which runs without being\n * connected to the speakers). Never throws: without Web Audio support it reports no samples, which the\n * watchdog and the handover check treat as \"no information\".\n */\nexport function createLevelMeter(audioContext, mediaStream, { pollMs = 100, threshold = VOICE_THRESHOLD_RMS, timers = defaultTimers, now = Date.now } = {}) {\n  const listeners = new Set();\n  let source = null;\n  let analyser = null;\n  let interval = null;\n  let buffer = null;\n  let lastVoicedAt = 0;\n  let working = false;\n  try {\n    source = audioContext.createMediaStreamSource(mediaStream);\n    analyser = audioContext.createAnalyser();\n    analyser.fftSize = 2048;\n    source.connect(analyser);\n    buffer = new Float32Array(analyser.fftSize);\n    working = true;\n    interval = timers.setInterval(() => {\n      let level = null;\n      try {\n        analyser.getFloatTimeDomainData(buffer);\n        let sum = 0;\n        for (let i = 0; i < buffer.length; i++) sum += buffer[i] * buffer[i];\n        level = Math.sqrt(sum / buffer.length);\n      } catch {\n        level = null;\n      }\n      if (level != null && level > threshold) lastVoicedAt = now();\n      listeners.forEach((fn) => {\n        try {\n          fn(level);\n        } catch {\n          /* a listener's failure must not stop the meter */\n        }\n      });\n    }, pollMs);\n  } catch {\n    working = false;\n  }\n  return {\n    get working() {\n      return working;\n    },\n    get lastVoicedAt() {\n      return lastVoicedAt;\n    },\n    onSample(fn) {\n      listeners.add(fn);\n      return () => listeners.delete(fn);\n    },\n    dispose() {\n      timers.clearInterval(interval);\n      interval = null;\n      listeners.clear();\n      try {\n        source?.disconnect();\n      } catch {\n        /* already disconnected */\n      }\n      try {\n        analyser?.disconnect();\n      } catch {\n        /* already disconnected */\n      }\n      source = null;\n      analyser = null;\n      working = false;\n    },\n  };\n}\n\n/**\n * Nova Sonic's view of the agent's microphone stream. Two differences from handing Nova Sonic the stream\n * itself: when the session's input loop ends, the microphone is NOT destroyed (the agent's Transcribe\n * listens to the same microphone and must keep hearing it while Nova Sonic is restarted), and close()\n * ends the session's input loop at once. Every explicit destroy() of the stream in main.js still applies.\n *\n * onFirstPull runs when the session starts reading. A drain (createStreamDrain) that kept the stream\n * empty while the session was starting stops there, so the session hears live audio, not a burst of\n * what was said while it started.\n */\nexport function createNovaInputView(stream, { onFirstPull } = {}) {\n  let closed = false;\n  let wake = null;\n  let pulled = false;\n  const view = {\n    get closed() {\n      return closed;\n    },\n    close() {\n      closed = true;\n      if (wake) {\n        const resolve = wake;\n        wake = null;\n        resolve({ value: undefined, done: true });\n      }\n    },\n    [Symbol.asyncIterator]() {\n      const iterator = stream[Symbol.asyncIterator]();\n      return {\n        next: () => {\n          if (closed) return Promise.resolve({ value: undefined, done: true });\n          if (!pulled) {\n            pulled = true;\n            try {\n              onFirstPull?.();\n            } catch {\n              /* the view must keep working */\n            }\n          }\n          return new Promise((resolve) => {\n            wake = resolve;\n            iterator.next().then(\n              (result) => {\n                if (wake !== resolve) return; // closed meanwhile: this chunk is dropped\n                wake = null;\n                resolve(result);\n              },\n              () => {\n                if (wake !== resolve) return;\n                wake = null;\n                resolve({ value: undefined, done: true });\n              },\n            );\n          });\n        },\n        return: () => {\n          closed = true;\n          wake = null;\n          return Promise.resolve({ value: undefined, done: true });\n        },\n      };\n    },\n  };\n  return view;\n}\n\n/**\n * Reads and discards a stream nobody else is reading (the agent's microphone while Nova Sonic is not\n * running), so its queue does not grow without bound. Never calls return(), which would destroy it.\n */\nexport function createStreamDrain(stream) {\n  let stopped = false;\n  const iterator = stream[Symbol.asyncIterator]();\n  (async () => {\n    while (!stopped) {\n      let result;\n      try {\n        result = await iterator.next();\n      } catch {\n        break;\n      }\n      if (result.done) break;\n    }\n  })();\n  return {\n    stop() {\n      stopped = true;\n    },\n    get stopped() {\n      return stopped;\n    },\n  };\n}\n\n/**\n * Keeps the forceBackupTranslation switch's value, refreshed every intervalMs. A failed read keeps the\n * last value; the first value is false until a read succeeds.\n */\nexport function createModePoller({ fetchMode, onChange, intervalMs = 30000, timers = defaultTimers, log = console }) {\n  let forceBackup = false;\n  let known = false;\n  let interval = null;\n  let failing = false;\n  let inFlight = null;\n\n  async function refresh() {\n    if (inFlight) return inFlight;\n    inFlight = (async () => {\n      try {\n        const mode = await fetchMode();\n        const next = mode?.forceBackup === true;\n        if (failing) log.info?.(\"[BACKUP] switch readable again\");\n        failing = false;\n        const changed = !known ? next : next !== forceBackup;\n        forceBackup = next;\n        known = true;\n        if (changed) onChange?.(forceBackup);\n      } catch (e) {\n        if (!failing) log.warn?.(`[BACKUP] could not read the switch, keeping ${forceBackup ? \"ON\" : \"off\"}`, e?.message || e);\n        failing = true;\n      } finally {\n        inFlight = null;\n      }\n    })();\n    return inFlight;\n  }\n\n  return {\n    start() {\n      if (interval) return;\n      refresh();\n      interval = timers.setInterval(refresh, intervalMs);\n    },\n    stop() {\n      timers.clearInterval(interval);\n      interval = null;\n    },\n    refresh,\n    get forceBackup() {\n      return forceBackup;\n    },\n  };\n}\n\n/** Per-call counters for the [BACKUP-SUMMARY] line. */\nexport function createBackupStats() {\n  const keys = [\"switches\", \"returns\", \"sentences\", \"delivered\", \"textOnly\", \"failed\", \"echoDropped\", \"failedAttempts\", \"backupMs\"];\n  const counts = { agent: {}, customer: {} };\n  const reset = () => {\n    for (const side of [\"agent\", \"customer\"]) keys.forEach((k) => (counts[side][k] = 0));\n    counts.typed = 0;\n  };\n  reset();\n  return {\n    inc(side, key, n = 1) {\n      if (counts[side] && key in counts[side]) counts[side][key] += n;\n    },\n    incTyped() {\n      counts.typed++;\n    },\n    get(side, key) {\n      return counts[side]?.[key] || 0;\n    },\n    hasActivity() {\n      return counts.typed > 0 || [\"agent\", \"customer\"].some((s) => keys.some((k) => counts[s][k] > 0));\n    },\n    summary() {\n      const part = (s) =>\n        `${s}: switched ${counts[s].switches}, back to Nova ${counts[s].returns}, sentences ${counts[s].sentences},` +\n        ` spoken ${counts[s].delivered}, text only ${counts[s].textOnly}, failed ${counts[s].failed},` +\n        ` echo dropped ${counts[s].echoDropped}, failed restarts ${counts[s].failedAttempts},` +\n        ` on backup ${Math.round(counts[s].backupMs / 1000)}s`;\n      return `${part(\"agent\")} | ${part(\"customer\")} | typed via backup ${counts.typed}`;\n    },\n    reset,\n  };\n}\n",
 "proxy/src/services/translationMode.js": "// Copyright 2025 Amazon.com, Inc. or its affiliates. All Rights Reserved.\n// SPDX-License-Identifier: MIT-0\nimport { GetParameterCommand } from \"@aws-sdk/client-ssm\";\nimport { errorFields } from \"../logger.js\";\n\n/**\n * fix 6: the forceBackupTranslation switch. Read from Parameter Store every refreshMs, so an\n * administrator can switch every call to the backup translation (Transcribe + Translate + Polly), and\n * back, without a deployment. The webapp asks for it through GET /api/translation-mode.\n *\n * Off unless the parameter's value is \"true\" (case and surrounding spaces ignored): a missing parameter,\n * or no parameter name configured, is off. A failed read keeps the last value, so a Parameter Store\n * hiccup never flips the calls.\n *\n * @param {object} opts\n * @param {{send(command): Promise<any>}|null} opts.ssm  SSM client, or null when the switch is not configured\n * @param {string|null} opts.parameterName\n */\nexport function createTranslationModeSource({ ssm, parameterName, refreshMs = 30_000, logger }) {\n  const enabled = Boolean(ssm && parameterName);\n  let forceBackup = false;\n  let timer = null;\n  let failing = false;\n  let reportedMissing = false;\n\n  async function refresh() {\n    if (!enabled) return forceBackup;\n    try {\n      const result = await ssm.send(new GetParameterCommand({ Name: parameterName }));\n      const next = String(result?.Parameter?.Value ?? \"\").trim().toLowerCase() === \"true\";\n      if (next !== forceBackup) logger.info(\"translation mode changed\", { parameterName, forceBackup: next });\n      if (failing) logger.info(\"translation mode parameter readable again\", { parameterName, forceBackup: next });\n      forceBackup = next;\n      failing = false;\n      reportedMissing = false;\n    } catch (err) {\n      if (err?.name === \"ParameterNotFound\") {\n        if (forceBackup) logger.info(\"translation mode changed\", { parameterName, forceBackup: false, reason: \"parameterNotFound\" });\n        else if (!reportedMissing) logger.info(\"translation mode parameter not found: backup switch is off\", { parameterName });\n        reportedMissing = true;\n        forceBackup = false;\n        failing = false;\n      } else {\n        if (!failing) {\n          logger.warn(\"could not read the translation mode parameter; keeping the last value\", {\n            parameterName,\n            forceBackup,\n            ...errorFields(err),\n          });\n        }\n        failing = true;\n      }\n    }\n    return forceBackup;\n  }\n\n  return {\n    get enabled() {\n      return enabled;\n    },\n    /** Reads the parameter now and every refreshMs after. Never throws. */\n    start() {\n      if (!enabled || timer) return Promise.resolve(forceBackup);\n      timer = setInterval(() => {\n        refresh();\n      }, refreshMs);\n      timer.unref?.();\n      return refresh();\n    },\n    stop() {\n      clearInterval(timer);\n      timer = null;\n    },\n    refresh,\n    current() {\n      return { forceBackup };\n    },\n  };\n}\n",
 "proxy/test/translationMode.test.js": "// Copyright 2025 Amazon.com, Inc. or its affiliates. All Rights Reserved.\n// SPDX-License-Identifier: MIT-0\n//\n// fix 6: the forceBackupTranslation switch (services/translationMode.js) and GET /api/translation-mode.\nimport { test } from \"node:test\";\nimport assert from \"node:assert/strict\";\nimport { loadConfig } from \"../src/config.js\";\nimport { createProxyServer } from \"../src/server.js\";\nimport { createTranslationModeSource } from \"../src/services/translationMode.js\";\nimport { VALID_TOKEN, fakeBedrock, fakePolly, fakeTranscribe, fakeTranslate, fakeVerifier, silentLogger, testConfig } from \"./helpers.js\";\n\nconst PARAM = \"/Abbvie/NovaSonic/Dev/forceBackupTranslation\";\n\n/** SSM fake: returns `state.value`, or throws `state.error`; records every parameter name asked for. */\nfunction fakeSsm(state) {\n  return {\n    names: [],\n    async send(command) {\n      this.names.push(command.input.Name);\n      if (state.error) throw state.error;\n      if (state.value === undefined) throw Object.assign(new Error(\"not found\"), { name: \"ParameterNotFound\" });\n      return { Parameter: { Name: command.input.Name, Value: state.value } };\n    },\n  };\n}\n\nfunction recordingLogger() {\n  const lines = [];\n  const log = (level) => (msg, fields) => lines.push({ level, msg, ...fields });\n  return { lines, debug: log(\"debug\"), info: log(\"info\"), warn: log(\"warn\"), error: log(\"error\") };\n}\n\nasync function startServer(translationMode) {\n  const proxy = createProxyServer({\n    config: testConfig(),\n    verifier: fakeVerifier,\n    logger: silentLogger,\n    clients: { bedrock: fakeBedrock(), transcribe: fakeTranscribe(), translate: fakeTranslate(), polly: fakePolly() },\n    translationMode,\n  });\n  const { port } = await proxy.listen(0, \"127.0.0.1\");\n  return { url: `http://127.0.0.1:${port}`, close: () => proxy.shutdown() };\n}\n\nconst getMode = (url, { token = VALID_TOKEN, method = \"GET\" } = {}) =>\n  fetch(`${url}/api/translation-mode`, { method, headers: token ? { Authorization: `Bearer ${token}` } : {} });\n\ntest(\"switch: only the value \\\"true\\\" (any case, spaces ignored) turns it on\", async () => {\n  for (const [value, expected] of [\n    [\"true\", true],\n    [\" TRUE \", true],\n    [\"True\", true],\n    [\"false\", false],\n    [\"yes\", false],\n    [\"1\", false],\n    [\"\", false],\n  ]) {\n    const source = createTranslationModeSource({ ssm: fakeSsm({ value }), parameterName: PARAM, logger: silentLogger });\n    assert.equal(await source.refresh(), expected, `value ${JSON.stringify(value)}`);\n    assert.deepEqual(source.current(), { forceBackup: expected });\n  }\n});\n\ntest(\"switch: a missing parameter is off, and is logged once\", async () => {\n  const logger = recordingLogger();\n  const state = { value: undefined };\n  const source = createTranslationModeSource({ ssm: fakeSsm(state), parameterName: PARAM, logger });\n  assert.equal(await source.refresh(), false);\n  assert.equal(await source.refresh(), false);\n  assert.equal(logger.lines.filter((l) => l.msg.includes(\"not found\")).length, 1);\n});\n\ntest(\"switch: turns on and off as the parameter changes; each change is logged\", async () => {\n  const logger = recordingLogger();\n  const state = { value: \"false\" };\n  const ssm = fakeSsm(state);\n  const source = createTranslationModeSource({ ssm, parameterName: PARAM, logger });\n  assert.equal(await source.refresh(), false);\n  state.value = \"true\";\n  assert.equal(await source.refresh(), true);\n  state.value = undefined; // deleted\n  assert.equal(await source.refresh(), false);\n  assert.deepEqual(ssm.names, [PARAM, PARAM, PARAM]);\n  const changes = logger.lines.filter((l) => l.msg === \"translation mode changed\");\n  assert.deepEqual(changes.map((c) => c.forceBackup), [true, false]);\n});\n\ntest(\"switch: a failed read keeps the last value, warns once, and recovers\", async () => {\n  const logger = recordingLogger();\n  const state = { value: \"true\" };\n  const source = createTranslationModeSource({ ssm: fakeSsm(state), parameterName: PARAM, logger });\n  assert.equal(await source.refresh(), true);\n  state.error = Object.assign(new Error(\"denied\"), { name: \"AccessDeniedException\" });\n  assert.equal(await source.refresh(), true);\n  assert.equal(await source.refresh(), true);\n  assert.equal(logger.lines.filter((l) => l.level === \"warn\").length, 1);\n  state.error = null;\n  state.value = \"false\";\n  assert.equal(await source.refresh(), false);\n  assert.ok(logger.lines.some((l) => l.msg === \"translation mode parameter readable again\"));\n});\n\ntest(\"switch: without a parameter name or SSM client it is off and never calls AWS\", async () => {\n  const ssm = fakeSsm({ value: \"true\" });\n  const noName = createTranslationModeSource({ ssm, parameterName: null, logger: silentLogger });\n  assert.equal(noName.enabled, false);\n  assert.equal(await noName.start(), false);\n  assert.equal(await noName.refresh(), false);\n  const noClient = createTranslationModeSource({ ssm: null, parameterName: PARAM, logger: silentLogger });\n  assert.equal(await noClient.refresh(), false);\n  assert.deepEqual(ssm.names, []);\n});\n\ntest(\"switch: start() reads at once and then every refreshMs; stop() ends it\", async () => {\n  const state = { value: \"false\" };\n  const ssm = fakeSsm(state);\n  const source = createTranslationModeSource({ ssm, parameterName: PARAM, refreshMs: 30, logger: silentLogger });\n  assert.equal(await source.start(), false);\n  state.value = \"true\";\n  await new Promise((r) => setTimeout(r, 100));\n  assert.equal(source.current().forceBackup, true);\n  source.stop();\n  const reads = ssm.names.length;\n  await new Promise((r) => setTimeout(r, 100));\n  assert.equal(ssm.names.length, reads);\n});\n\ntest(\"config: FORCE_BACKUP_PARAMETER and SSM_REGION, with their defaults\", () => {\n  const base = { COGNITO_USER_POOL_ID: \"p\", COGNITO_CLIENT_ID: \"c\", BEDROCK_REGION: \"us-west-2\", NOVA_MODEL_ID: \"m\" };\n  const off = loadConfig(base);\n  assert.equal(off.forceBackupParameter, null);\n  assert.equal(off.ssmRegion, \"us-west-2\");\n  assert.equal(off.timeouts.translationModeRefreshMs, 30000);\n  assert.equal(off.limits.fallbackRequestsPerMinute, 60);\n  const on = loadConfig({ ...base, FORCE_BACKUP_PARAMETER: ` ${PARAM} `, SSM_REGION: \"us-east-1\", FALLBACK_REQUESTS_PER_MINUTE: \"150\" });\n  assert.equal(on.forceBackupParameter, PARAM);\n  assert.equal(on.ssmRegion, \"us-east-1\");\n  assert.equal(on.limits.fallbackRequestsPerMinute, 150);\n  assert.equal(loadConfig({ ...base, AWS_REGION: \"eu-west-1\" }).ssmRegion, \"eu-west-1\");\n});\n\ntest(\"GET /api/translation-mode: needs a valid token, returns the switch, is never cached\", async () => {\n  const state = { value: \"true\" };\n  const source = createTranslationModeSource({ ssm: fakeSsm(state), parameterName: PARAM, logger: silentLogger });\n  await source.refresh();\n  const server = await startServer(source);\n  try {\n    assert.equal((await getMode(server.url, { token: null })).status, 401);\n    assert.equal((await getMode(server.url, { token: \"forged.token\" })).status, 401);\n    assert.equal((await getMode(server.url, { method: \"POST\" })).status, 405);\n    const on = await getMode(server.url);\n    assert.equal(on.status, 200);\n    assert.equal(on.headers.get(\"cache-control\"), \"no-store\");\n    assert.deepEqual(await on.json(), { forceBackup: true });\n    state.value = \"false\";\n    await source.refresh();\n    assert.deepEqual(await (await getMode(server.url)).json(), { forceBackup: false });\n  } finally {\n    await server.close();\n  }\n});\n\ntest(\"GET /api/translation-mode: off when the server has no switch configured\", async () => {\n  const server = await startServer(undefined);\n  try {\n    const res = await getMode(server.url);\n    assert.equal(res.status, 200);\n    assert.deepEqual(await res.json(), { forceBackup: false });\n  } finally {\n    await server.close();\n  }\n});\n"
};

